package com.gamehubstore.notification_mscv.models; import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.LocalDateTime;
@Entity @Table(name="notifications") public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull @Column(nullable=false) private Long userId; @NotBlank @Column(nullable=false) private String type; @NotBlank @Size(max=2000) @Column(nullable=false,length=2000) private String message; @Column(nullable=false) private boolean read=false; @Column(nullable=false) private boolean archived=false; @Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();
 public Long getId(){return id;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public boolean isRead(){return read;} public void setRead(boolean v){read=v;} public boolean isArchived(){return archived;} public void setArchived(boolean v){archived=v;} public LocalDateTime getCreatedAt(){return createdAt;}}
